package com.thakur.employee.model;
import jakarta.persistence.*;import jakarta.validation.constraints.*;import lombok.*;import java.math.*;import java.time.*;
@Entity @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Expense { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private AppUser employee; @NotBlank private String category; @NotNull @DecimalMin("0.01") private BigDecimal amount; @NotBlank @Column(length=500) private String description; @NotNull private LocalDate expenseDate; @Enumerated(EnumType.STRING) private RequestStatus status; private String financeComment; private LocalDateTime createdAt; @PrePersist void pre(){if(status==null)status=RequestStatus.PENDING;if(createdAt==null)createdAt=LocalDateTime.now();} }
